import{c as r,Q as t,j as a,m as o}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"How to Increase Your Loading Speed","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/increase-loading-speed.md","filePath":"how-to/increase-loading-speed.md"}'),i={name:"how-to/increase-loading-speed.md"};function s(n,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="how-to-increase-your-loading-speed" tabindex="-1">How to Increase Your Loading Speed <a class="header-anchor" href="#how-to-increase-your-loading-speed" aria-label="Permalink to &quot;How to Increase Your Loading Speed&quot;">​</a></h1><p>Website speed is a critical factor for user retention. It has been proven that if your loading speed is too slow, visitors will leave before the page finishes loading.</p><h2 id="basics-first" tabindex="-1">Basics First <a class="header-anchor" href="#basics-first" aria-label="Permalink to &quot;Basics First&quot;">​</a></h2><ul><li>Use tools like <a href="https://tools.pingdom.com/" target="_blank" rel="noreferrer">Pingdom</a> to analyze your current loading speed.</li><li>Make sure you have a <a href="./../general/recommended-web-hosts.html">reliable web host</a> that meets the <a href="./../general/server-requirements.html">minimum server requirements</a>.</li><li>Optimize your images for the web: <strong>max 2000px wide, 2500px tall, and around 500KB per image</strong>.</li></ul><h2 id="caching-and-optimization-plugins" tabindex="-1">Caching and Optimization Plugins <a class="header-anchor" href="#caching-and-optimization-plugins" aria-label="Permalink to &quot;Caching and Optimization Plugins&quot;">​</a></h2><p>Once your theme is installed, you may notice it is slower than the demo. This is because our demos run a cache system. Here are the 3 plugins we use on all our demos:</p><ol><li><a href="https://wordpress.org/plugins/ewww-image-optimizer/" target="_blank" rel="noreferrer">EWWW Image Optimizer</a> — automatically compresses images on upload.</li><li><a href="https://wordpress.org/plugins/wp-super-cache/" target="_blank" rel="noreferrer">WP Super Cache</a> — generates static HTML files to serve visitors faster.</li><li><a href="https://wordpress.org/plugins/autoptimize/" target="_blank" rel="noreferrer">Autoptimize</a> — minifies and combines CSS/JS files.</li></ol><blockquote><p><strong>Important for Autoptimize:</strong> uncheck the <strong>&quot;Also aggregate inline CSS&quot;</strong> option, and add <a href="https://gist.github.com/wolfthemes/68c9cb5c3f5ebc3e56d9115204c945a9" target="_blank" rel="noreferrer">this exclusion line</a> to the <strong>&quot;Exclude scripts from Autoptimize&quot;</strong> field.</p></blockquote><h2 id="cdn" tabindex="-1">CDN <a class="header-anchor" href="#cdn" aria-label="Permalink to &quot;CDN&quot;">​</a></h2><p>For even faster loading, use a <a href="https://www.wpbeginner.com/beginners-guide/why-you-need-a-cdn-for-your-wordpress-blog-infographic/" target="_blank" rel="noreferrer">CDN (Content Delivery Network)</a> to serve your static assets (images, videos, etc.) from servers closer to your visitors. We use and recommend <a href="https://bunny.net?ref=cta4iplkoi" target="_blank" rel="noreferrer">Bunny.net</a>.</p><hr><p><strong>Want to skip the hassle? <a href="https://wolfthemes.com/services/" target="_blank" rel="noreferrer">Explore our speed optimization service</a></strong></p>',12)])])}const g=r(i,[["render",s]]);export{u as __pageData,g as default};
